alter table public.transport_schedules add column bus_id uuid references public.transport_buses(id) on delete restrict, add column operating_days smallint[] not null default '{}', add column valid_from date, add column valid_until date, add column active boolean not null default false, add column delay_threshold_minutes integer not null default 5;
alter table public.transport_schedules add constraint schedule_days_valid check (operating_days <@ array[1,2,3,4,5,6,7]::smallint[]), add constraint schedule_date_order check (valid_from is null or valid_until is null or valid_until>=valid_from), add constraint schedule_threshold_valid check (delay_threshold_minutes between 1 and 60), add constraint schedule_active_complete check (not active or (bus_id is not null and cardinality(operating_days)>0 and valid_from is not null and valid_until is not null));
create index schedule_bus_active on public.transport_schedules(bus_id,active,valid_from,valid_until);
create table public.transport_schedule_stops(schedule_id uuid not null references public.transport_schedules(id) on delete cascade, stop_id uuid not null references public.transport_stops(id) on delete restrict, arrival_time time not null, primary key(schedule_id,stop_id));
alter table public.transport_schedule_stops enable row level security;
revoke all on public.transport_schedule_stops from public,anon,authenticated;
grant select on public.transport_schedule_stops to authenticated;
create policy schedule_stops_admin_read on public.transport_schedule_stops for select to authenticated using ((select public.is_transport_admin()));
create policy schedule_student_read on public.transport_schedules for select to authenticated using (active and bus_id is not null and public.can_read_assigned_gps(bus_id));
create policy schedule_stops_assigned_read on public.transport_schedule_stops for select to authenticated using (exists(select 1 from public.transport_schedules s where s.id=schedule_id and s.active and public.can_read_assigned_gps(s.bus_id)));
create function public.validate_schedule_record() returns trigger language plpgsql security definer set search_path='' as $$ begin
 if new.bus_id is not null then perform pg_advisory_xact_lock(hashtextextended(new.bus_id::text,0)); if not exists(select 1 from public.transport_buses where id=new.bus_id and route_id=new.route_id) then raise exception 'Bus must be assigned to the selected route'; end if; end if;
 if new.active and exists(select 1 from public.transport_schedules s where s.id<>new.id and s.active and s.bus_id=new.bus_id and s.departure_time=new.departure_time and s.operating_days && new.operating_days and daterange(s.valid_from,s.valid_until,'[]') && daterange(new.valid_from,new.valid_until,'[]')) then raise exception 'Conflicting active departure for this bus, day and validity period'; end if;
 return new; end $$;
create trigger schedule_validate before insert or update on public.transport_schedules for each row execute function public.validate_schedule_record();
create function public.guard_scheduled_bus_route() returns trigger language plpgsql security definer set search_path='' as $$ begin perform pg_advisory_xact_lock(hashtextextended(old.id::text,0)); if new.route_id is distinct from old.route_id and exists(select 1 from public.transport_schedules where bus_id=old.id and active and route_id is distinct from new.route_id) then raise exception 'Deactivate the bus schedules before changing its route'; end if; return new; end $$;
create trigger scheduled_bus_route_guard before update of route_id on public.transport_buses for each row execute function public.guard_scheduled_bus_route();
create function public.save_transport_schedule(p_id uuid,p_bus uuid,p_route uuid,p_period text,p_departure time,p_days smallint[],p_from date,p_until date,p_active boolean,p_threshold integer,p_notes text,p_stops jsonb) returns uuid language plpgsql security definer set search_path='' as $$ declare sid uuid; entry jsonb; lastpos int:=-1; lasttime time:=p_departure; pos int; atime time; stop uuid; begin
 if not public.is_transport_admin() then raise exception 'Not authorized' using errcode='42501'; end if;
 if p_bus is null or p_route is null or p_days is null or cardinality(p_days)=0 or p_from is null or p_until is null or p_until<p_from or p_threshold not between 1 and 60 or p_stops is null or jsonb_typeof(p_stops)<>'array' then raise exception 'Complete all required schedule fields'; end if;
 if p_id is null then insert into public.transport_schedules(bus_id,route_id,service_period,departure_time,operating_days,valid_from,valid_until,active,delay_threshold_minutes,notes) values(p_bus,p_route,p_period,p_departure,p_days,p_from,p_until,p_active,p_threshold,p_notes) returning id into sid; else update public.transport_schedules set bus_id=p_bus,route_id=p_route,service_period=p_period,departure_time=p_departure,operating_days=p_days,valid_from=p_from,valid_until=p_until,active=p_active,delay_threshold_minutes=p_threshold,notes=p_notes where id=p_id returning id into sid; if sid is null then raise exception 'Schedule not found'; end if; end if;
 delete from public.transport_schedule_stops where schedule_id=sid;
 for entry in select value from jsonb_array_elements(p_stops) loop stop:=(entry->>'stop_id')::uuid; atime:=(entry->>'arrival_time')::time; select position into pos from public.transport_route_stops where route_id=p_route and stop_id=stop; if pos is null or pos<=lastpos or atime is null or atime<lasttime then raise exception 'Stop times must be in route order and not earlier than the previous time'; end if; insert into public.transport_schedule_stops values(sid,stop,atime); lastpos:=pos; lasttime:=atime; end loop;
 return sid; end $$;
revoke all on function public.save_transport_schedule(uuid,uuid,uuid,text,time,smallint[],date,date,boolean,integer,text,jsonb),public.validate_schedule_record(),public.guard_scheduled_bus_route() from public,anon,authenticated;
grant execute on function public.save_transport_schedule(uuid,uuid,uuid,text,time,smallint[],date,date,boolean,integer,text,jsonb) to authenticated;
create function public.my_schedule_context() returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('bus_id',b.id,'bus_number',b.bus_number,'route_id',b.route_id,'route_name',r.name,'pickup_stop_id',a.pickup_stop_id,'stops',coalesce((select jsonb_agg(jsonb_build_object('id',st.id,'name',st.name,'latitude',st.latitude,'longitude',st.longitude) order by rs.position) from public.transport_route_stops rs join public.transport_stops st on st.id=rs.stop_id where rs.route_id=b.route_id),'[]'::jsonb),'schedules',coalesce((select jsonb_agg(jsonb_build_object('id',sc.id,'period',sc.service_period,'departure',sc.departure_time,'days',sc.operating_days,'valid_from',sc.valid_from,'valid_until',sc.valid_until,'threshold',sc.delay_threshold_minutes,'notes',sc.notes,'stop_times',coalesce((select jsonb_object_agg(ss.stop_id::text,ss.arrival_time::text) from public.transport_schedule_stops ss where ss.schedule_id=sc.id),'{}'::jsonb)) order by sc.departure_time) from public.transport_schedules sc where sc.bus_id=b.id and sc.route_id=b.route_id and sc.active and sc.valid_until >= (now() at time zone 'Asia/Kolkata')::date),'[]'::jsonb),'active_trip',(select jsonb_build_object('id',t.id,'started_at',t.started_at) from public.transport_trips t where t.bus_id=b.id and t.route_id=b.route_id and t.status='active' order by t.started_at desc limit 1),'historical_seconds',(select avg(extract(epoch from t.ended_at-t.started_at)) from public.transport_trips t where t.bus_id=b.id and t.route_id=b.route_id and t.status='completed' and t.ended_at-t.started_at between interval '5 minutes' and interval '4 hours')) from public.profiles p join public.transport_assignments a on a.student_id=p.student_id join public.transport_buses b on b.id=a.bus_id left join public.transport_routes r on r.id=b.route_id where p.id=auth.uid() and p.role='student'
$$;
revoke all on function public.my_schedule_context() from public,anon;
grant execute on function public.my_schedule_context() to authenticated;
alter publication supabase_realtime add table public.transport_schedules, public.transport_schedule_stops;
